const items = $input.all().map(i => i.json || {});
const minItems = 5;
const maxItems = 100;
const normalizeMetric = (value) => {
  const n = Number(String(value ?? '0').replace(/[^0-9]/g, ''));
  return Number.isFinite(n) ? n : 0;
};
const repoPattern = /^[^\s/]+\/[^\s/]+$/;
const normalized = [];
const seen = new Set();
let reason = '';
for (let i = 0; i < items.length; i++) {
  const rawPath = String(items[i].repoPath || '').trim().replace(/^\/+|\/+$/g, '');
  if (!repoPattern.test(rawPath)) { reason = `invalid_repo_at_rank_${i + 1}`; break; }
  if (seen.has(rawPath)) { reason = `duplicate_repo_${rawPath}`; break; }
  seen.add(rawPath);
  normalized.push({
    rank: i + 1,
    repoFullName: rawPath,
    repoUrl: `https://github.com/${rawPath}`,
    description: String(items[i].description || '').trim(),
    language: String(items[i].language || '').trim(),
    stars: normalizeMetric(items[i].starsText),
    forks: normalizeMetric(items[i].forksText),
    addedStars: normalizeMetric(items[i].addedStarsLabel),
  });
}
if (!reason && (normalized.length < minItems || normalized.length > maxItems)) reason = `item_count_${normalized.length}_outside_${minItems}_${maxItems}`;
const usable = !reason;
if (!usable) return [{ json: { usable: false, reason, itemCount: normalized.length, rows: [] } }];
const hashInput = JSON.stringify(normalized);
let h = 0x811c9dc5;
for (let i = 0; i < hashInput.length; i++) { h ^= hashInput.charCodeAt(i); h = Math.imul(h, 0x01000193); }
const contentHash = (h >>> 0).toString(16).padStart(8, '0');
const collectedAt = new Date().toISOString();
const snapshotDate = $now.setZone('Asia/Shanghai').toFormat('yyyy-MM-dd');
const snapshotId = `daily:all:${snapshotDate}:official:${contentHash}`;
const itemCount = normalized.length;
const rows = normalized.map(r => ({
  snapshotKey: `${snapshotId}:${r.rank}`,
  snapshotId,
  contentHash,
  snapshotDate,
  period: 'daily',
  languageScope: 'all',
  ...r,
  source: 'github_trending_html',
  sourceAuthority: 'direct_official',
  sourceUrl: 'https://github.com/trending?since=daily',
  sourcePublishedAt: null,
  collectedAt,
  freshnessStatus: 'fresh',
  schemaVersion: 2,
  itemCount,
  collectorStatus: 'healthy',
}));
return [{ json: { usable: true, reason: '', snapshotId, contentHash, snapshotDate, itemCount, source: 'github_trending_html', sourceAuthority: 'direct_official', sourceUrl: 'https://github.com/trending?since=daily', sourcePublishedAt: null, collectedAt, freshnessStatus: 'fresh', schemaVersion: 2, collectorStatus: 'healthy', rows } }];

const payload = $input.first()?.json || {};
const minItems = 5;
const maxItems = 100;
const pubMs = Date.parse(payload.pubDate || '');
const ageMs = Date.now() - pubMs;
let reason = '';
if (!Number.isFinite(pubMs)) reason = 'invalid_or_missing_pubDate';
if (!reason && (ageMs < -3600000 || ageMs > 86400000)) reason = `mirror_age_ms_${ageMs}_outside_window`;
if (!reason && !Array.isArray(payload.items)) reason = 'items_not_array';
const rawItems = Array.isArray(payload.items) ? payload.items : [];
if (!reason && (rawItems.length < minItems || rawItems.length > maxItems)) reason = `item_count_${rawItems.length}_outside_${minItems}_${maxItems}`;
const normalized = [];
const seen = new Set();
const urlPattern = /^https:\/\/github\.com\/([^\s/]+)\/([^\s/#?]+)\/?$/i;
const metric = (value) => {
  const n = Number(String(value ?? '0').replace(/[^0-9]/g, ''));
  return Number.isFinite(n) ? n : 0;
};
if (!reason) {
  for (let i = 0; i < rawItems.length; i++) {
    const url = String(rawItems[i]?.url || '').trim();
    const m = url.match(urlPattern);
    if (!m) { reason = `invalid_repo_url_at_rank_${i + 1}`; break; }
    const repoFullName = `${m[1]}/${m[2]}`;
    if (seen.has(repoFullName)) { reason = `duplicate_repo_${repoFullName}`; break; }
    seen.add(repoFullName);
    normalized.push({ rank: i + 1, repoFullName, repoUrl: `https://github.com/${repoFullName}`, description: String(rawItems[i]?.description || '').trim(), language: String(rawItems[i]?.language || '').trim(), stars: metric(rawItems[i]?.stars), forks: metric(rawItems[i]?.forks), addedStars: metric(rawItems[i]?.added_stars) });
  }
}
if (reason) return [{ json: { usable: false, reason, itemCount: normalized.length, rows: [] } }];
