for (let i = 0; i < hashInput.length; i++) { h ^= hashInput.charCodeAt(i); h = Math.imul(h, 0x01000193); }
const contentHash = (h >>> 0).toString(16).padStart(8, '0');
const sourcePublishedAt = new Date(pubMs).toISOString();
const snapshotDate = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(pubMs));
const collectedAt = new Date().toISOString();
const snapshotId = `daily:all:${snapshotDate}:mirror:${contentHash}`;
const itemCount = normalized.length;
const rows = normalized.map(r => ({ snapshotKey: `${snapshotId}:${r.rank}`, snapshotId, contentHash, snapshotDate, period: 'daily', languageScope: 'all', ...r, source: 'hanishrao_trending_collection', sourceAuthority: 'mirror_of_official', sourceUrl: 'https://github.com/hanishrao/trending-collection/blob/main/api/daily/all.json', sourcePublishedAt, collectedAt, freshnessStatus: 'fresh', schemaVersion: 2, itemCount, collectorStatus: 'degraded-primary' }));
return [{ json: { usable: true, reason: '', snapshotId, contentHash, snapshotDate, itemCount, source: 'hanishrao_trending_collection', sourceAuthority: 'mirror_of_official', sourceUrl: 'https://github.com/hanishrao/trending-collection/blob/main/api/daily/all.json', sourcePublishedAt, collectedAt, freshnessStatus: 'fresh', schemaVersion: 2, collectorStatus: 'degraded-primary', rows } }];

const candidate = $('Stage validated candidate').first().json;
const current = $input.first()?.json || {};
const same = current.stateKey === 'daily:all:current' && current.snapshotId === candidate.snapshotId && current.contentHash === candidate.contentHash && Number(current.itemCount) === Number(candidate.itemCount) && Number(current.schemaVersion) === 2;
return [{ json: { ...candidate, commitNeeded: !same, previousSnapshotId: current.snapshotId || null } }];

const candidate = $input.first()?.json || {};
if (!candidate.commitNeeded || !Array.isArray(candidate.rows)) return [];
return candidate.rows.map(row => ({ json: row }));

const state = $('Read current snapshot state for LKG').first()?.json || {};
const rows = $input.all().map(i => i.json || {}).filter(r => r.snapshotId);
let reason = '';
if (state.stateKey !== 'daily:all:current' || !state.snapshotId) reason = 'missing_current_state';
const expected = Number(state.itemCount || 0);
if (!reason && (Number(state.schemaVersion) !== 2 || expected < 5 || expected > 100)) reason = 'invalid_state_contract';
const freshnessBase = Date.parse(state.sourcePublishedAt || state.collectedAt || '');
const ageMs = Date.now() - freshnessBase;
if (!reason && (!Number.isFinite(freshnessBase) || ageMs < -3600000 || ageMs > 172800000)) reason = 'lkg_stale_or_invalid_time';
if (!reason && rows.length !== expected) reason = `row_count_${rows.length}_expected_${expected}`;
if (!reason) {
  const ranks = new Set();
  const repos = new Set();
  for (const r of rows) {
    if (r.snapshotId !== state.snapshotId || r.contentHash !== state.contentHash || Number(r.schemaVersion) !== 2 || Number(r.itemCount) !== expected) { reason = 'row_metadata_mismatch'; break; }
    const rank = Number(r.rank);
    if (!Number.isInteger(rank) || rank < 1 || rank > expected || ranks.has(rank)) { reason = 'invalid_or_duplicate_rank'; break; }
    ranks.add(rank);
    const repo = String(r.repoFullName || '');
    if (!/^[^\s/]+\/[^\s/]+$/.test(repo) || repos.has(repo)) { reason = 'invalid_or_duplicate_repo'; break; }
    repos.add(repo);
  }
  if (!reason && ranks.size !== expected) reason = 'rank_set_incomplete';
}
if (reason) return [{ json: { usable: false, collectorStatus: 'unavailable', reason, snapshotId: state.snapshotId || null } }];
return [{ json: { usable: true, collectorStatus: 'degraded-lkg', reason: '', snapshotId: state.snapshotId, snapshotDate: state.snapshotDate, source: state.source, sourceAuthority: state.sourceAuthority, sourceUrl: state.sourceUrl, sourcePublishedAt: state.sourcePublishedAt || null, collectedAt: state.collectedAt, itemCount: expected, schemaVersion: 2, freshnessStatus: 'lkg', ageMs } }];

